<?php require 'includes/auth.php';require_role('buyer');require 'includes/order_service.php';$pending=$_SESSION['pending_checkout']??null;if(!$pending||($pending['payment_method']??'')!=='UPI_DEMO'){flash('error','Start your UPI demo checkout first.');redirect('checkout.php');}$items=buyer_cart_items(user()['id']);if(!$items){unset($_SESSION['pending_checkout']);flash('error','Your cart is empty.');redirect('cart.php');}$total=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items))+($pending['delivery_type']==='delivery'?50:0);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!hash_equals($pending['token'],post('checkout_token')))exit('Invalid payment request.');try{$id=create_marketplace_order(user()['id'],(int)$pending['address_id'],$pending['delivery_type'],'UPI_DEMO','paid');unset($_SESSION['pending_checkout']);flash('success','Demo UPI payment recorded as paid. Your order is confirmed.');redirect('order-details.php?id='.$id);}catch(Throwable $e){$error=$e->getMessage();}}$pageTitle='UPI demo payment';require 'includes/header.php';?><div class="payment-page"><p class="eyebrow">SIMULATED PAYMENT</p><h1>Scan to Pay</h1><p class="payment-total">₹<?=number_format($total,2)?></p><div class="demo-qr" aria-label="Demo UPI QR code"><span>FRESH<br>CATCH</span></div><p><b>UPI ID:</b> freshcatch@upi</p><p class="muted">Demo payment only — no real money is transferred.</p><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="checkout_token" value="<?=e($pending['token'])?>"><button>I've Completed Payment · ₹<?=number_format($total,2)?></button></form><p><a href="checkout.php">← Back to checkout</a></p></div><?php require 'includes/footer.php'; ?>
